import json, glob
def cmds(tid):
    try: d=json.load(open(tid+'.messages.json'))
    except: return None
    out=[]
    for m in d:
        if m.get('role')=='assistant':
            for tc in (m.get('tool_calls') or []):
                try:
                    args=json.loads(tc['function']['arguments']); out.append(args.get('command',''))
                except: out.append('<err>')
    return out
def max_run(cs):
    best=1;cur=1
    for i in range(1,len(cs)):
        if cs[i]==cs[i-1] and cs[i].strip(): cur+=1; best=max(best,cur)
        else: cur=1
    return best
# also count total repeated (any identical anywhere)
import collections
allt=[f.replace('.result.json','') for f in glob.glob('*.result.json')]
loopers=[]
for tid in sorted(allt):
    d=json.load(open(tid+'.result.json'))
    ex=d.get('agent',{}).get('exit_reason'); rew=d.get('reward')
    cs=cmds(tid)
    if not cs: continue
    mr=max_run(cs)
    c=collections.Counter(cs)
    mostcommon=c.most_common(1)[0][1] if cs else 0
    tag='LOOP' if mr>=3 else '    '
    if mr>=3 or ex=='budget_exceeded':
        print(f'{tag} {tid} rew={rew} exit={str(ex):16} n_cmds={len(cs)} maxConsecDup={mr} mostCommonCmd={mostcommon}')
"

